"""The CIRCT ``fsm`` dialect: explicit finite state machines.

A machine is a symbol whose body is a *graph region* of ``fsm.state``
operations; each state owns its outgoing ``fsm.transition`` operations plus an
optional ``fsm.output`` terminator.  That nesting is the whole dialect - the
interesting part is that it is directly executable:

* :meth:`TransitionOp.is_enabled` evaluates a Python guard against a signal
  environment, the same ``env`` mapping the simulator in
  :mod:`src.circt.simulator` builds for the combinational dialects.
* :meth:`MachineOp.step` takes the first enabled transition out of the current
  state, and :meth:`MachineOp.run` drives one environment per cycle.

:class:`StateEncoding` is the bridge back to hardware: it says how a state index
becomes a bit pattern, so :meth:`MachineOp.state_width` can report how wide the
machine's state register has to be.
"""
from __future__ import annotations

from enum import Enum
from typing import Any, Callable, Dict, List, Optional, Sequence, Union

from mlir.ir import (
    ArrayAttr,
    Attribute,
    Block,
    Dialect,
    FlatSymbolRefAttr,
    FunctionType,
    Location,
    Operation,
    Region,
    StringAttr,
    Trait,
    Type,
    TypeAttr,
    Value,
    get_default_context,
)
from .hw_dialect import Direction, HWModuleOp, HWOp, IntType, Port, SignalEnv

__all__ = [
    "FSM_DIALECT",
    "StateEncoding",
    "MachineOp",
    "StateOp",
    "TransitionOp",
    "FSMOutputOp",
]

FSM_DIALECT = Dialect("fsm", get_default_context())

#: A guard is any callable from a signal environment to something truthy.
Guard = Callable[[SignalEnv], Any]


def _string_attr(op: Operation, *names: str) -> str:
    """The first of ``names`` present on ``op``, rendered as a plain string.

    The parser and the hand-written constructors do not agree on where a name
    lands: ``fsm.state @A`` parses into ``sym_name`` while a machine built in
    Python may spell it ``name``.  Reading through a list of candidates keeps the
    accessors working either way, and works on a generic
    :class:`~src.mlir.ir.Operation` too.
    """
    for name in names:
        attr = op.attributes.get(name)
        if attr is not None:
            return str(attr.value)
    return ""


class StateEncoding(Enum):
    """How a state index is encoded into the machine's state register.

    The three styles are the ones a hardware compiler actually offers: dense
    binary, one bit per state, and Gray code (adjacent states differ in exactly
    one bit, which halves the switching activity of a walking counter).
    """

    BINARY = "binary"
    ONE_HOT = "one_hot"
    GRAY = "gray"

    @staticmethod
    def parse(text: Union[str, "StateEncoding"]) -> "StateEncoding":
        if isinstance(text, StateEncoding):
            return text
        needle = str(text).lower().replace("-", "_")
        for candidate in StateEncoding:
            if needle in (candidate.value, candidate.name.lower()):
                return candidate
        raise ValueError(f"unknown state encoding {text!r}")

    def encode(self, index: int, num_states: int = 0) -> int:
        """The bit pattern state ``index`` gets under this encoding."""
        index = int(index)
        if index < 0:
            raise ValueError(f"state index must be non-negative, got {index}")
        if num_states and index >= num_states:
            raise ValueError(
                f"state index {index} out of range for {num_states} states"
            )
        if self is StateEncoding.ONE_HOT:
            return 1 << index
        if self is StateEncoding.GRAY:
            return index ^ (index >> 1)
        return index

    def width_for(self, num_states: int) -> int:
        """How many register bits ``num_states`` states need.

        One-hot needs one bit per state; binary and Gray both need
        ``ceil(log2(num_states))`` bits, and never fewer than one.
        """
        num_states = int(num_states)
        if num_states <= 1:
            return 1
        if self is StateEncoding.ONE_HOT:
            return num_states
        return (num_states - 1).bit_length()


# ---------------------------------------------------------------------------
# Operations
# ---------------------------------------------------------------------------


class FSMOutputOp(HWOp):
    """``fsm.output %a, %b : i4, i4`` - the terminator of a state's region.

    Mirrors :class:`~src.circt.hw_dialect.OutputOp`: ``evaluate`` returns one
    integer per operand, which is what a state drives onto the machine's output
    ports while it is active.
    """

    OPERATION_NAME = "fsm.output"
    TRAITS = (Trait.TERMINATOR, Trait.PURE)

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(operands=operands, location=location)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    def evaluate(self, env: Optional[SignalEnv] = None) -> List[int]:
        return self.read_operands(env or {})

    def fold(self) -> Optional[List[Any]]:
        return None


class TransitionOp(HWOp):
    """``fsm.transition @Next`` - one edge out of the enclosing state.

    The target is stored as a symbol reference rather than a successor block,
    because ``fsm`` states are operations, not blocks.  ``guard`` is an optional
    Python callable taking the signal environment; a transition without one is
    unconditional, which is how a state's default edge is spelled.
    """

    OPERATION_NAME = "fsm.transition"

    #: Class-level default so ``guard`` is readable even when ``build_parsed``
    #: (which bypasses ``__init__``) created the operation.
    guard: Optional[Guard] = None

    def __init__(
        self,
        target: Optional[str] = None,
        guard: Optional[Guard] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if target:
            attrs.setdefault("target", FlatSymbolRefAttr(target))
        super().__init__(
            operands=operands,
            attributes=attrs,
            location=location,
        )
        self.guard = guard

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        # A parsed guard lives in a region, not in a Python callable, so the
        # transition is unconditional as far as ``is_enabled`` is concerned.
        op.guard = None
        return op

    # -- accessors --------------------------------------------------------
    @property
    def target(self) -> str:
        """The name of the state this transition goes to (``""`` if unset)."""
        return _string_attr(self, "target", "next_state", "sym_name")

    @property
    def is_always_taken(self) -> bool:
        return self.guard is None

    def is_enabled(self, env: Optional[SignalEnv] = None) -> bool:
        """Is this transition's guard satisfied by ``env``?"""
        if self.guard is None:
            return True
        if callable(self.guard):
            return bool(self.guard(env or {}))
        # A non-callable guard is treated as a constant condition, which keeps
        # hand-built machines readable: ``TransitionOp("B", guard=False)``.
        return bool(self.guard)

    def verify_op(self) -> List[str]:
        if not self.target:
            return ["'fsm.transition' requires a target state"]
        return []

    def __repr__(self) -> str:
        suffix = "" if self.is_always_taken else " [guarded]"
        return f"TransitionOp(-> {self.target or '?'}{suffix})"


class StateOp(HWOp):
    """``fsm.state @A { ... }`` - a named state and its outgoing edges.

    The region holds the state's :class:`TransitionOp` operations followed by an
    optional :class:`FSMOutputOp`.  The output comes last because it is a
    terminator and :meth:`~src.mlir.ir.Block.verify` requires terminators to end
    their block, even though CIRCT writes the ``output`` clause first.
    """

    OPERATION_NAME = "fsm.state"
    TRAITS = (Trait.SYMBOL, Trait.SINGLE_BLOCK)

    def __init__(
        self,
        name: Optional[str] = None,
        transitions: Optional[Sequence[TransitionOp]] = None,
        output: Optional[FSMOutputOp] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("sym_name", StringAttr(name))
        super().__init__(attributes=attrs, location=location)
        block = self.region(self.add_region(Region()) and 0).add_block(Block())
        for transition in transitions or ():
            block.append(transition)
        if output is not None:
            block.append(output)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    # -- structure --------------------------------------------------------
    @property
    def block(self) -> Optional[Block]:
        if not self.regions or not self.regions[0].blocks:
            return None
        return self.regions[0].blocks[0]

    @property
    def body(self) -> List[Operation]:
        """Every operation in the state, flattened across blocks and regions.

        The parser may hand a state more than one region (CIRCT spells the
        output and the transitions as two region clauses), so this does not
        assume a single entry block.
        """
        return [op for region in self.regions for op in region.operations]

    @property
    def state_name(self) -> str:
        return _string_attr(self, "sym_name", "name")

    @property
    def transitions(self) -> List[TransitionOp]:
        return [
            op
            for op in self.body
            if isinstance(op, TransitionOp)
            or op.name == TransitionOp.OPERATION_NAME
        ]

    @property
    def output_op(self) -> Optional[Operation]:
        for op in reversed(self.body):
            if op.name == FSMOutputOp.OPERATION_NAME:
                return op
        return None

    def add_transition(self, transition: TransitionOp) -> TransitionOp:
        """Append ``transition``, keeping any ``fsm.output`` terminator last."""
        block = self.block
        if block is None:
            block = self.body_region().add_block(Block())
        terminator = block.terminator
        if terminator is not None:
            block.insert_before(terminator, transition)
        else:
            block.append(transition)
        return transition

    def body_region(self) -> Region:
        """The state's region, created on demand."""
        if not self.regions:
            self.add_region(Region())
        return self.regions[0]

    # -- execution --------------------------------------------------------
    def next_state(self, env: Optional[SignalEnv] = None) -> Optional[str]:
        """The target of the first enabled transition, ``None`` if none fires.

        Transitions are tried in textual order, so an unconditional edge acts as
        the default only when it is written last.
        """
        env = env or {}
        for transition in self.transitions:
            if transition.is_enabled(env) and transition.target:
                return transition.target
        return None

    def evaluate(self, env: Optional[SignalEnv] = None) -> List[int]:
        """The values this state drives, taken from its ``fsm.output``."""
        output = self.output_op
        if output is None:
            return []
        return output.evaluate(env or {})

    def verify_op(self) -> List[str]:
        if not self.state_name:
            return ["'fsm.state' requires a 'sym_name' attribute"]
        return []

    def __repr__(self) -> str:
        return f"StateOp(@{self.state_name or '?'}, {len(self.transitions)} transitions)"


class MachineOp(HWOp):
    """``fsm.machine @Name(%in: i1) -> (i1) { fsm.state ... }``.

    The body is a graph region of :class:`StateOp` operations.  ``fsm.machine``
    is listed in the parser's ``PORT_LIST_OPS``, so a parsed machine carries the
    same ``sym_name`` / ``function_type`` / ``port_names`` / ``port_directions``
    attributes as ``hw.module`` and exposes them through :attr:`ports`.

    The machine is also an interpreter: :attr:`current_state` starts at
    :attr:`initial_state`, :meth:`step` advances it by one transition and
    :meth:`run` replays a list of per-cycle environments.
    """

    OPERATION_NAME = "fsm.machine"
    TRAITS = (Trait.SYMBOL, Trait.ISOLATED_FROM_ABOVE, Trait.GRAPH_REGION)

    #: Class-level defaults so attribute access never raises on an operation
    #: created by ``build_parsed``, which bypasses ``__init__``.
    encoding: StateEncoding = StateEncoding.BINARY
    _current_state: Optional[str] = None

    def __init__(
        self,
        name: Optional[str] = None,
        initial_state: Optional[str] = None,
        encoding: Union[str, StateEncoding] = StateEncoding.BINARY,
        states: Optional[Sequence[StateOp]] = None,
        ports: Optional[Sequence[Port]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        port_list = list(ports or ())
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("sym_name", StringAttr(name))
        if initial_state:
            attrs.setdefault("initialState", StringAttr(initial_state))
        resolved = StateEncoding.parse(encoding)
        attrs.setdefault("stateEncoding", StringAttr(resolved.value))
        if port_list:
            attrs.setdefault(
                "port_names", ArrayAttr([StringAttr(p.name) for p in port_list])
            )
            attrs.setdefault(
                "port_directions",
                ArrayAttr([StringAttr(p.direction.value) for p in port_list]),
            )
            attrs.setdefault(
                "function_type",
                TypeAttr(
                    FunctionType(
                        [p.port_type for p in port_list if not p.is_output and p.port_type],
                        [p.port_type for p in port_list if p.is_output and p.port_type],
                    )
                ),
            )
        super().__init__(attributes=attrs, location=location)
        self.encoding = resolved
        self._current_state = None

        block = self.add_region(Region()).add_block(Block())
        for port in port_list:
            if not port.is_output:
                block.add_argument(port.port_type or IntType(1), port.name)
        for state in states or ():
            block.append(state)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        declared = _string_attr(op, "stateEncoding", "encoding")
        try:
            op.encoding = StateEncoding.parse(declared) if declared else StateEncoding.BINARY
        except ValueError:
            op.encoding = StateEncoding.BINARY
        op._current_state = None
        return op

    # -- structure --------------------------------------------------------
    @property
    def machine_name(self) -> Optional[str]:
        attr = self.attributes.get("sym_name")
        return attr.value if attr is not None else None

    #: ``Operation.name`` is the mnemonic, so the symbol is also spelled out
    #: under the MLIR-standard ``sym_name`` name.
    @property
    def sym_name(self) -> Optional[str]:
        return self.machine_name

    @property
    def block(self) -> Optional[Block]:
        if not self.regions or not self.regions[0].blocks:
            return None
        return self.regions[0].blocks[0]

    @property
    def body(self) -> List[Operation]:
        """The operations in the machine body, in textual order."""
        return [op for region in self.regions for op in region.operations]

    @property
    def ports(self) -> List[Port]:
        """The machine's ports, when it was built from a port list.

        Decoding ``port_names`` / ``port_directions`` / ``function_type`` is
        identical to ``hw.module``, so reuse that accessor instead of repeating
        the input/output index bookkeeping.
        """
        return HWModuleOp.ports.fget(self)  # type: ignore[attr-defined]

    @property
    def input_ports(self) -> List[Port]:
        return [p for p in self.ports if not p.is_output]

    @property
    def output_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_output]

    # -- states -----------------------------------------------------------
    @property
    def states(self) -> List[StateOp]:
        return [
            op
            for op in self.body
            if isinstance(op, StateOp) or op.name == StateOp.OPERATION_NAME
        ]

    def state_names(self) -> List[str]:
        return [_string_attr(state, "sym_name", "name") for state in self.states]

    def find_state(self, name: Optional[str]) -> Optional[StateOp]:
        if not name:
            return None
        needle = name.lstrip("@")
        for state in self.states:
            if _string_attr(state, "sym_name", "name") == needle:
                return state
        return None

    @property
    def num_states(self) -> int:
        return len(self.states)

    @property
    def initial_state(self) -> Optional[str]:
        """The declared initial state, defaulting to the first state in the body."""
        declared = _string_attr(self, "initialState", "initial_state")
        if declared:
            return declared
        names = self.state_names()
        return names[0] if names else None

    def add_state(self, state: StateOp) -> StateOp:
        """Append ``state`` to the machine body, creating the region if needed."""
        if not self.regions:
            self.add_region(Region())
        region = self.regions[0]
        block = region.entry_block or region.add_block(Block())
        block.append(state)
        return state

    # -- encoding ---------------------------------------------------------
    def state_width(self) -> int:
        """How many bits the state register needs under the current encoding."""
        return self.encoding.width_for(self.num_states)

    def encode_state(self, name: Optional[str]) -> int:
        """The bit pattern for state ``name`` (0 when the state is unknown)."""
        names = self.state_names()
        target = (name or "").lstrip("@")
        if target not in names:
            return 0
        return self.encoding.encode(names.index(target), len(names))

    # -- execution --------------------------------------------------------
    @property
    def current_state(self) -> Optional[str]:
        """Where the machine is now, lazily initialised to the initial state."""
        if self._current_state is None:
            self._current_state = self.initial_state
        return self._current_state

    @current_state.setter
    def current_state(self, name: Optional[str]) -> None:
        self._current_state = name

    def reset_state(self) -> Optional[str]:
        """Return the machine to its initial state."""
        self._current_state = self.initial_state
        return self._current_state

    def step(self, env: Optional[SignalEnv] = None) -> Optional[str]:
        """Take one transition out of the current state and return the new one.

        A state with no enabled transition holds its value, which is what the
        hardware does: the state register simply reloads itself.
        """
        state = self.find_state(self.current_state)
        if state is None:
            return self.reset_state()
        target = state.next_state(env or {})
        if target and self.find_state(target) is not None:
            self._current_state = target
        return self._current_state

    def run(
        self,
        inputs_per_cycle: Optional[Sequence[SignalEnv]] = None,
        reset: bool = True,
    ) -> List[Optional[str]]:
        """Drive one environment per cycle, returning the state after each.

        With ``reset=False`` the walk continues from :attr:`current_state`, so a
        long trace can be built in pieces.
        """
        if reset:
            self.reset_state()
        return [self.step(env) for env in inputs_per_cycle or ()]

    def outputs(self, env: Optional[SignalEnv] = None) -> List[int]:
        """What the current state drives, via its ``fsm.output``."""
        state = self.find_state(self.current_state)
        return state.evaluate(env or {}) if state is not None else []

    # -- verification -----------------------------------------------------
    def verify_op(self) -> List[str]:
        errors: List[str] = []
        if self.machine_name is None:
            errors.append("'fsm.machine' requires a 'sym_name' attribute")
        names = self.state_names()
        seen: set = set()
        for name in names:
            if name in seen:
                errors.append(f"Duplicate state name: {name}")
            seen.add(name)
        declared = _string_attr(self, "initialState", "initial_state")
        if declared and names and declared not in names:
            errors.append(f"initial state '{declared}' is not defined")
        for state in self.states:
            if not isinstance(state, StateOp):
                continue
            for transition in state.transitions:
                target = transition.target
                if names and target and target not in names:
                    errors.append(
                        f"state '{state.state_name}' transitions to unknown state "
                        f"'{target}'"
                    )
        return errors

    def __repr__(self) -> str:
        return (
            f"MachineOp(@{self.machine_name or '?'}, {self.num_states} states, "
            f"{self.encoding.value})"
        )


for _op in (
    MachineOp,
    StateOp,
    TransitionOp,
    FSMOutputOp,
):
    FSM_DIALECT.register_operation(_op)
del _op

